4class Board {
5
6    // count variable
7    int count = 0;
8
9    // create an ArrayList
10    ArrayList<String> board = new ArrayList<>();
11
12    // add elements to the board ArrayList
13    void addElements() {
14        board.add(" ");
15        board.add(" ");
16        board.add(" ");
17        board.add(" ");
18        board.add(" ");
19        board.add(" ");
20        board.add(" ");
21        board.add(" ");
22        board.add(" ");
23    }
24
25    // print elements of the board
26    void printBoard() {
27
28        System.out.println(" " + board.get(0) + " | " + board.get(1) + " | " + board.get(2));
29        System.out.println("-----------");
30        System.out.println(" " + board.get(3) + " | " + board.get(4) + " | " + board.get(5));
31        System.out.println("-----------");
32        System.out.println(" " + board.get(6) + " | " + board.get(7) + " | " + board.get(8));
33
34    }
35
36    boolean updateBoard(int position, String type) {
37
38        // if a player selects position n, n-1 index should be updated
39        // if the position is not already filled, update the board
40        if (board.get(position - 1) == (" ")) {
41            board.set(position - 1, type);
42
43            // increase the value of count by 1
44            count = count + 1;
45
46            return true;
47        }
48
49        // if the position is already filled, ask user to select another position
50        else {
51            System.out.println("Position already selected. Select another position.");
52            return false;
53
54        }
55    }
56
57    // if all fields are selected and there is no winner, it's draw
58    // returning true if it's draw
59    boolean checkDraw() {
60
61        // check if count == 9
62        if (count == 9) {
63            return true;
64        } else {
65            return false;
66        }
67    }
68
69    // if three symbols appears in a row, returning true
70    boolean checkWinner(String type) {
71        if ((board.get(0).equals(type) && board.get(1).equals(type) && board.get(2).equals(type))
72                || (board.get(3).equals(type) && board.get(4).equals(type) && board.get(5).equals(type))
73                || (board.get(6).equals(type) && board.get(7).equals(type) && board.get(8).equals(type))
74                || (board.get(0).equals(type) && board.get(3).equals(type) && board.get(6).equals(type))
75                || (board.get(1).equals(type) && board.get(4).equals(type) && board.get(7).equals(type))
76                || (board.get(2).equals(type) && board.get(5).equals(type) && board.get(8).equals(type))
77                || (board.get(0).equals(type) && board.get(4).equals(type) && board.get(8).equals(type))
78                || (board.get(2).equals(type) && board.get(4).equals(type) && board.get(6).equals(type))) {
79            return true;
80        }
81
82        else {
83            return false;
84        }
85
86    }
87}
