108class Game {
109
110    // create object of Board class
111    Board b1 = new Board();
112
113    // create object of Player class
114    Player player1 = new Player("X");
115    Player player2 = new Player("O");
116
117    // set currentPlayer as player1
118    Player currentPlayer = player1;
119
120    void play() {
121
122        // call add elements method
123        b1.addElements();
124        // using an infinite loop to run the game
125        // we will later add conditions to terminate the loop
126        String message = "enter the position (1 - 9):";
127        while (true) {
128
129            message = "enter the position (1 - 9):";
130            System.out.println(currentPlayer.name + " " + message);
131            Scanner input = new Scanner(System.in);
132            int position = input.nextInt();
133
134            // the updateBoard() method return true if
135            // the user selected position is not already filled
136            if (b1.updateBoard(position, currentPlayer.type)) {
137
138                b1.printBoard();
139
140
141                // checking winner each time after updating the board
142                if (b1.checkWinner(currentPlayer.type)) {
143                    System.out.println(currentPlayer.name + " wins!");
144                    break;
145                }
146
147                // checking draw each time after updating the board
148                else if (b1.checkDraw()) {
149                    System.out.println("Game is a draw!");
150                    break;
151                }
152                // changing current player when board is updated
153                else {
154                    if (currentPlayer == player1) {
155                        currentPlayer = player2;
156                    }
157
158                    else {
159                        currentPlayer = player1;
160                    }
161                }
162
163            }
164        }
165    }
166}
